<script setup lang="ts">
import { computed,onMounted,ref } from "vue";import CpfIcon from "../../components/CpfIcon.vue";import { bzaApi,hasBzaMenu } from "../auth/session";
const summary=ref<Record<string,number>>({}),approvals=ref<Record<string,any>[]>([]),organizations=ref<Record<string,any>[]>([]),employees=ref<Record<string,any>[]>([]),error=ref("");
const pending=computed(()=>approvals.value.filter(r=>String(r.actionableYn||'').toUpperCase()==='Y'));
async function load(){error.value='';try{const tasks=[bzaApi('/api/bza/dashboard'),hasBzaMenu('APPROVAL')?bzaApi('/api/bza/approvals/inbox?decisionStatus=WAITING&limit=12'):Promise.resolve([]),hasBzaMenu('ORGANIZATION')?bzaApi('/api/bza/backoffice/organizations?limit=300'):Promise.resolve([]),hasBzaMenu('EMPLOYEE')?bzaApi('/api/bza/backoffice/employees?limit=300'):Promise.resolve([])];const[d,a,o,e]=await Promise.all(tasks);summary.value=d as Record<string,number>;approvals.value=a as any[];organizations.value=o as any[];employees.value=e as any[]}catch(e){error.value=e instanceof Error?e.message:String(e)}}onMounted(load);
</script><template><div class="page-stack"><div class="cpf-page-heading"><div><p class="eyebrow">BUSINESS CONTROL</p><h2>업무 운영 대시보드</h2><p>조직·사람·권한·결재에서 지금 처리해야 할 업무를 우선순위로 보여줍니다.</p></div><button class="ghost" @click="load"><CpfIcon name="refresh"/> 새로고침</button></div><p v-if="error" class="error-banner">{{error}}</p><section class="cpf-kpi-grid"><article class="cpf-stat-card"><span class="label">활성 직원</span><strong class="value">{{summary.activeEmployeeCount??employees.length}}</strong><span class="sub">조직 {{organizations.length}}</span></article><article class="cpf-stat-card"><span class="label">진행 결재</span><strong class="value">{{summary.pendingApprovalCount??pending.length}}</strong><span class="cpf-status warning">Action required</span></article><article class="cpf-stat-card"><span class="label">미확인 알림</span><strong class="value">{{summary.unreadNotificationCount??0}}</strong></article><article class="cpf-stat-card"><span class="label">오늘 감사</span><strong class="value">{{summary.todayAuditCount??0}}</strong></article></section><div class="cpf-grid-2"><section class="cpf-card"><div class="cpf-card-head"><div><p class="eyebrow">APPROVAL</p><h2>결재 진행</h2></div></div><ul class="cpf-timeline"><li v-for="r in approvals.slice(0,8)" :key="String(r.approvalId)"><div class="cpf-node-title"><strong>{{r.title||r.approvalNo}}</strong><span class="cpf-status" :class="String(r.approvalStatus).includes('REJECT')?'danger':'info'">{{r.approvalStatus}}</span></div><p>{{r.requesterEmployeeNo||'-'}} · Step {{r.currentStepNo??'-'}} · {{r.updatedAt||''}}</p></li><li v-if="!approvals.length" class="cpf-empty">최근 결재가 없습니다.</li></ul></section><section class="cpf-card"><div class="cpf-card-head"><div><p class="eyebrow">ORGANIZATION</p><h2>조직 Snapshot</h2></div></div><div class="cpf-card-body"><div class="bza-org-summary"><div><strong>{{organizations.length}}</strong><span>조직</span></div><div><strong>{{employees.length}}</strong><span>직원</span></div><div><strong>{{summary.activeUserCount??0}}</strong><span>활성 사용자</span></div></div><p class="cpf-note">조직과 결재 참여자는 상신 시점 Snapshot으로 고정하여 이후 조직 변경과 분리합니다.</p></div></section></div></div></template>
